                    <?php foreach($trackedEvent['professors']as$professor):if($professor['status']==='COMPLETO')continue;?>
                        <article class="tracking-professor-card is-<?=strtolower(e($professor['status']))?>"><header><div><strong><?=e($professor['professor_nome'])?></strong><a href="<?=e($context->url(['aba'=>'files','evento'=>$trackedEvent['id'],'professor'=>$professor['professor_usuario_id'],'pagina'=>'','q'=>'','situacao'=>'','formato'=>'']))?>">Biblioteca deste evento/professor</a><small><?=e($professor['sent_count'])?> de <?=e($professor['total_count'])?> turma(s) enviada(s)</small></div><span class="badge <?=$professor['status']==='PARCIAL'?'status-enviado':'status-devolvido'?>"><?=$professor['status']==='PARCIAL'?'Envio parcial':'Ainda não enviou'?></span></header><div class="tracking-requirements"><strong>Falta enviar:</strong><ul><?php foreach($professor['missing']as$requirement):?><li><span><?=e($requirement['turma_nome'])?></span><small><?=e($requirement['rotulo_etapa'])?> · <?=e($requirement['rotulo_serie'])?><?php if($requirement['vinculo_atual_alterado']??false):?> · vínculo atual alterado; pendência histórica preservada<?php endif;?></small></li><?php endforeach;?></ul></div></article>
                    <?php endforeach;?></div><?php endif;?>
                </section>
                <details class="apc-complete-professors"><summary><span><strong>Professores que concluíram</strong><small><?=e($trackedEvent['complete_count'])?> professor(es)</small></span><span>Ver lista</span></summary><?php if(!$trackedEvent['complete_count']):?><p class="tracking-group-empty">Nenhum professor concluiu todos os envios deste evento.</p><?php else:?><div class="tracking-professor-list complete-list">
                    <?php foreach($trackedEvent['professors']as$professor):if($professor['status']!=='COMPLETO')continue;?>
                        <article class="tracking-professor-card is-completo"><header><div><strong><?=e($professor['professor_nome'])?></strong><a href="<?=e($context->url(['aba'=>'files','evento'=>$trackedEvent['id'],'professor'=>$professor['professor_usuario_id'],'pagina'=>'','q'=>'','situacao'=>'','formato'=>'']))?>">Biblioteca deste evento/professor</a><small><?=e($professor['total_count'])?> turma(s) enviada(s)</small></div><span class="badge status-aprovado">Enviou tudo</span></header><ul class="tracking-sent-series"><?php foreach($professor['requirements']as$requirement):?><li><?=e($requirement['turma_nome'])?> <small><?=e($requirement['rotulo_serie'])?></small></li><?php endforeach;?></ul></article>
                    <?php endforeach;?></div><?php endif;?></details>
                <?php endif;?>
            </div>
        </details>
        <?php endforeach;?>
    </div><?php endif;?>
    <?php if($tracking['without_series']):?><div class="error apc-binding-warning" role="alert"><strong>Vínculos que precisam de conferência</strong><p>Não foi possível identificar etapa e série para: <?=e(implode(', ',array_column($tracking['without_series'],'professor_nome')))?>. Confira os nomes das turmas e os vínculos ativos no Conselho de Classe.</p></div><?php endif;?>
</section>
</div>

