evento_data'])))?></span><span><?=e($stageLabels[$item['etapa']]??$item['etapa'])?></span><span><?=e($yearLabels[$item['ano_serie']]??$item['ano_serie'])?></span></div><?php if($legacyWithoutClass):?><small>Envio anterior sem turma individual definida.</small><?php endif;?></div><div class="submission-file"><small>Arquivo anexado</small><strong><?=e($item['nome_original'])?></strong><small><?=e(number_format((int)$item['tamanho_bytes']/1024,1,',','.'))?> KB · <?=e(date('d/m/Y H:i',strtotime($item['enviado_em'])))?></small><div class="submission-file-actions"><a class="button primary" href="/apc/envios/<?=e($item['id'])?>/visualizar?<?=e($context->query(['aba'=>'files']))?>">Visualizar</a><a class="button" href="/apc/envios/<?=e($item['id'])?>/arquivo">Baixar</a><form method="post" action="/apc/envios/<?=e($item['id'])?>/excluir"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><?php foreach(array_replace($context->filters,['aba'=>'files','pagina'=>$libraryPage['page']]) as$key=>$value):?><input type="hidden" name="<?=e($key)?>" value="<?=e($value)?>"><?php endforeach;?><button class="danger" data-confirm="Excluir definitivamente este envio? A turma voltará a ficar pendente.">Excluir</button></form></div></div></div></article><?php endforeach;?></div></details><?php endforeach;?></div><div class="empty-state compact" data-apc-file-empty hidden><h3>Nenhum arquivo encontrado</h3><p>Altere os filtros para visualizar outros envios.</p></div><?php endif;?>
